      // 图没解码出来（或者环境根本没有 Image）就不等了，直接出结果 ——
      // 动画是锦上添花，不能把流程卡住
      var im2 = struggleSheet(fishing.pendingResult && fishing.pendingResult.encounter.speciesId);
      var ready2 = im2 && im2 !== 'loading' && im2.width;
