  // ---------- 导航：可走多边形 + 阻挡矩形，按脚底判定 ----------
  var ACTOR_R = 5; // 脚底半径，斗笠和鱼竿不参与碰撞

  function pointInPoly(x, y, poly) {
    var inside = false;
    for (var i = 0, j = poly.length - 1; i < poly.length; j = i++) {
      var xi = poly[i][0], yi = poly[i][1], xj = poly[j][0], yj = poly[j][1];
      if (((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi)) inside = !inside;
    }
    return inside;
  }
  function inBlocker(x, y, b) {
    return x >= b[0] - ACTOR_R && x <= b[0] + b[2] + ACTOR_R &&
           y >= b[1] - ACTOR_R && y <= b[1] + b[3] + ACTOR_R;
  }
  function walkableIn(sceneName, x, y) {
    var nav = M.navigation[sceneName];
    if (!nav) return true;
    var polys = nav.walkablePolygons || [];
    if (polys.length) {
      var inside = false;
      for (var i = 0; i < polys.length; i++) {
        if (pointInPoly(x, y, polys[i])) { inside = true; break; }
      }
      if (!inside) return false;
    }
    var bl = nav.blockers || [];
    for (var k = 0; k < bl.length; k++) if (inBlocker(x, y, bl[k])) return false;
    return true;
  }
  function walkable(x, y) { return walkableIn(state.scene, x, y); }

  /** 尝试移动：分轴滑动，撞墙时贴着走而不是卡死 */
  function tryMove(dx, dy) {
    var x = state.feet[0], y = state.feet[1];
    if (dx && walkable(x + dx, y)) x += dx;
    if (dy && walkable(x, y + dy)) y += dy;
    state.feet[0] = x; state.feet[1] = y;
  }

  // ---------- 输入：隐形摇杆 + 轻点寻路 ----------
  var TOUCH_SLOP = 8, DEAD = 6, MAX_R = 46, SPEED = 46; // 像素/秒
