      var sh = state.ship;
      if (sh.appeared && sh.crashSeen &&
          Math.hypot(state.feet[0] - SHIP_ENTRY[0], state.feet[1] - SHIP_ENTRY[1]) < SHIP_ENTRY_R) {
        return sh.stage >= 5 ? 'ship' : 'shipBroken';
      }
      // 岸边靠近海神雕像：加满了就能交易，没加满只给提示
      if (Math.hypot(state.feet[0] - STATUE_STAND[0], state.feet[1] - STATUE_STAND[1]) < 24) {
        return state.poseidonAwake ? 'poseidon' : 'poseidonLocked';
      }
      // 必须站在桥的边缘，不是整块桥面都行。
      // 判断办法：往外 10 像素就是海，说明脚下就是边。
      // 站在水边最外一圈就能钓 —— 桥上、礁石、沙滩都算，不限于码头。
