  var EDGE_R = 6;
  /** 站在水边最外一圈：脚下还在陆地，但外面一小步就是海 */
  function atWaterEdge(x, y) {
    for (var a = 0; a < 16; a++) {
      var t = a / 16 * Math.PI * 2;
      if (isSea(x + Math.cos(t) * EDGE_R, y + Math.sin(t) * EDGE_R)) return true;
    }
    return false;
  }

  function atDockEdge(x, y) {
    if (!onDock(x, y)) return false;
    for (var a = 0; a < 12; a++) {
      var t = a / 12 * Math.PI * 2;
      if (isSea(x + Math.cos(t) * EDGE_R, y + Math.sin(t) * EDGE_R)) return true;
    }
    return false;
  }

  /** 海：可走区域之外、且在水面高度带里。灯塔塔身不算海（v3.2.1：灯塔两侧的草地也能钓了） */
  function isSea(x, y) {
    var nav = M.navigation.coast || {};
    var polys = nav.walkablePolygons || [];
    for (var i = 0; i < polys.length; i++) if (pointInPoly(x, y, polys[i])) return false;
    var ns = nav.notSea || [];
    for (var k = 0; k < ns.length; k++) {
      var r = ns[k];
      if (x >= r[0] && x <= r[0] + r[2] && y >= r[1] && y <= r[1] + r[3]) return false;
    }
    return y >= 80 && y <= 600;
  }

